gelu_hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

// Fast GELU using tanh approximation:
// GELU(x) = 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
__device__ __forceinline__ float gelu_fast(float x) {
    const float sqrt_2_over_pi = 0.7978845608028654f;
    const float coef = 0.044715f;
    float x3 = x * x * x;
    float inner = sqrt_2_over_pi * (x + coef * x3);
    return 0.5f * x * (1.0f + tanhf(inner));
}

// Vectorized GELU kernel using float4 for coalesced memory access
__global__ void gelu_kernel_vec4(const float4* __restrict__ input, 
                                  float4* __restrict__ output,
                                  int n_vec4) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < n_vec4; i += stride) {
        float4 in_val = input[i];
        float4 out_val;
        out_val.x = gelu_fast(in_val.x);
        out_val.y = gelu_fast(in_val.y);
        out_val.z = gelu_fast(in_val.z);
        out_val.w = gelu_fast(in_val.w);
        output[i] = out_val;
    }
}

// Scalar kernel for remaining elements
__global__ void gelu_kernel_scalar(const float* __restrict__ input,
                                    float* __restrict__ output,
                                    int start_idx,
                                    int total_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x + start_idx;
    if (idx < total_size) {
        output[idx] = gelu_fast(input[idx]);
    }
}

torch::Tensor gelu_hip(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "Input must be float32");

    auto output = torch::empty_like(input);
    int total_size = input.numel();

    // Use vectorized kernel for bulk of data
    int n_vec4 = total_size / 4;
    int remainder = total_size % 4;

    const int block_size = 256;

    if (n_vec4 > 0) {
        int num_blocks = min((n_vec4 + block_size - 1) / block_size, 65535);
        gelu_kernel_vec4<<<num_blocks, block_size>>>(
            reinterpret_cast<const float4*>(input.data_ptr<float>()),
            reinterpret_cast<float4*>(output.data_ptr<float>()),
            n_vec4
        );
    }

    // Handle remaining elements with scalar kernel
    if (remainder > 0) {
        int start_idx = n_vec4 * 4;
        int num_blocks_scalar = (remainder + block_size - 1) / block_size;
        gelu_kernel_scalar<<<num_blocks_scalar, block_size>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            start_idx,
            total_size
        );
    }

    return output;
}

