    int M = A.size(0);
    int K = A.size(1);

    auto C = torch::zeros({M, 1}, A.options());

    dim3 block(BLOCK_SIZE);
    dim3 grid(M);

    matvec_kernel_v2<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
