matmul_hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define BLOCK_SIZE 16
#define K_SIZE 32

// Optimized kernel for tall-skinny matrix multiplication
// A: (M, K), B: (K, M), C: (M, M) where K is small (32)
// Each thread computes one element of C
__global__ void tall_skinny_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K) {

    // Each block computes a BLOCK_SIZE x BLOCK_SIZE tile of C
    int row = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int col = blockIdx.x * BLOCK_SIZE + threadIdx.x;

    // Shared memory for A and B tiles
    __shared__ float As[BLOCK_SIZE][K_SIZE];
    __shared__ float Bs[K_SIZE][BLOCK_SIZE];

    // Load A tile: each row of BLOCK_SIZE threads loads K elements cooperatively
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Load A tile (BLOCK_SIZE rows x K cols)
    for (int k = tx; k < K_SIZE; k += BLOCK_SIZE) {
        if (row < M && k < K) {
            As[ty][k] = A[row * K + k];
        } else {
            As[ty][k] = 0.0f;
        }
    }

    // Load B tile (K rows x BLOCK_SIZE cols)
    for (int k = ty; k < K_SIZE; k += BLOCK_SIZE) {
        if (k < K && col < M) {
            Bs[k][tx] = B[k * M + col];
        } else {
            Bs[k][tx] = 0.0f;
        }
    }

    __syncthreads();

    // Compute dot product
    if (row < M && col < M) {
        float sum = 0.0f;
        #pragma unroll
        for (int k = 0; k < K_SIZE; k++) {
            sum += As[ty][k] * Bs[k][tx];
        }
        C[row * M + col] = sum;
    }
}

torch::Tensor tall_skinny_matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);

    auto C = torch::empty({M, M}, A.options());

    dim3 block(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid((M + BLOCK_SIZE - 1) / BLOCK_SIZE, (M + BLOCK_SIZE - 1) / BLOCK_SIZE);

    tall_skinny_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
