    int K = A.size(1);

    auto C = torch::zeros({M, 1}, A.options());

    dim3 block(BLOCK_SIZE);
    dim3 grid(M * BLOCKS_PER_ROW);

    matvec_atomic_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
