        dim3 grid(
            (output_width + block.x - 1) / block.x,
            (output_height + block.y - 1) / block.y,
            batch_size * channels
        );

        maxpool2d_kernel_generic<<<grid, block>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            batch_size,
            channels,
            input_height,
            input_width,
            output_height,
            output_width,
            kernel_size,
            stride,
            padding,
            dilation
        );
    }

    return output;
}
